<script setup>
import { computed, onMounted, ref, toRaw, watch } from 'vue'
import UniversalAdminForm from '../components/admin/UniversalAdminForm.vue'
import BackupRestorePanel from '../components/admin/BackupRestorePanel.vue'
import SyntheticDataPanel from '../components/admin/SyntheticDataPanel.vue'
import { ADMIN_FORM_DEFINITIONS } from '../application/admin/adminFormDefinitions.js'
import { AdminService } from '../application/admin/adminService.js'
import { BackupService } from '../application/backup/backupService.js'
import { LoanReadModelService } from '../application/admin/loanReadModelService.js'
import { PerformanceService } from '../application/performance/performanceService.js'
import { getKfeReferenceNow } from '../domain/time/ist.js'
import { deriveLoanPosition, calculatePrepaymentEstimate, paymentAllocationPreview } from '../domain/finance/loanEngine.js'
import { getKfeThemeSettings, setKfeThemeMode } from '../presentation/theme/kfeThemeController.js'

const groups=[
 {key:'businessSetup',title:'Business Setup',icon:'◉',forms:['vehicle','driver'],description:'Core vehicle and driver master data.'},
 {key:'vehicleRecords',title:'Vehicle Records',icon:'▣',forms:['compliance','maintenance'],description:'Vehicle compliance and maintenance records.'},
 {key:'finance',title:'Finance',icon:'₹',forms:['loan','prepayment'],description:'Live loan position, payments and prepayments.'},
 {key:'planningControls',title:'Planning & Controls',icon:'⌁',forms:['driverTarget','breakEvenInputs'],description:'Effective-dated targets and break-even inputs.'}
]
const settingsMenu=[
 {key:'backup',title:'Backup & Restore',subtitle:'Protect and recover complete KFE data',icon:'↥'},
 {key:'application',title:'Application Settings',subtitle:'Application-level preferences and controls',icon:'⚙'},
 {key:'reset',title:'Data Reset',subtitle:'Clear the canonical KFE dataset',icon:'⚠'},
 {key:'synthetic',title:'Synthetic Data',subtitle:'Isolated test dataset only',icon:'🧪'}
]
const adminSection=ref('records'),selected=ref('vehicle'),settingsSelected=ref('backup'),categoryTouchStartX=ref(null)
const adminNavigationStorageKey='kfe-admin-navigation-v1'
function restoreAdminNavigation(){try{const saved=JSON.parse(localStorage.getItem(adminNavigationStorageKey)||'null');if(!saved)return;if(saved.adminSection==='records')adminSection.value='records';else if(saved.adminSection==='settings')adminSection.value='settings';if(groups.some(g=>g.forms.includes(saved.selected)))selected.value=saved.selected;if(settingsMenu.some(item=>item.key===saved.settingsSelected))settingsSelected.value=saved.settingsSelected}catch(_e){}}
function persistAdminNavigation(){try{localStorage.setItem(adminNavigationStorageKey,JSON.stringify({adminSection:adminSection.value,selected:selected.value,settingsSelected:settingsSelected.value}))}catch(_e){}}
const themeSettings=ref(getKfeThemeSettings())
const records=ref([]),editing=ref(null),draft=ref({}),formOpen=ref(false),loading=ref(false),error=ref(''),notice=ref('')
const actionKey=ref(null),actionRecord=ref(null),actionDraft=ref({}),paymentCalculated=ref(false),paymentConfirmed=ref(false)
const prepaymentDraft=ref({loanId:'',paidOn:new Date().toISOString().slice(0,10),amount:0,reason:'',notes:''}),prepaymentCalculated=ref(false),prepaymentConfirmed=ref(false)
const money=value=>Number.isFinite(Number(value))?`₹${Number(value).toLocaleString('en-IN',{maximumFractionDigits:2})}`:'—'
const cloneForForm=value=>structuredClone(toRaw(value))
const all=ref({vehicle:[],driver:[],loan:[],compliance:[],maintenance:[],loanPayment:[],prepayment:[],settlement:[]})
const loanReadModel=ref({loans:[]})
const performanceSnapshot=ref(null),performanceMetrics=ref(null)
const currentGroup=computed(()=>groups.find(g=>g.forms.includes(selected.value))||groups[0])
const baseDefinition=computed(()=>ADMIN_FORM_DEFINITIONS[selected.value])
const activeDefinition=computed(()=>{const d=cloneForForm(baseDefinition.value);if(selected.value==='settlement')d.fields=d.fields.filter(f=>f.key!=='settlementType');for(const f of d.fields){if(f.key==='vehicleId')f.options=all.value.vehicle.map(x=>({value:x.id,label:label('vehicle',x)}));if(f.key==='driverId')f.options=all.value.driver.map(x=>({value:x.id,label:label('driver',x)}));if(f.key==='loanId')f.options=all.value.loan.map(x=>({value:x.id,label:label('loan',x)}));if(selected.value==='settlement'&&f.key==='sourceId'){const type=draft.value.sourceType||'Maintenance';f.options=(type==='Maintenance'?all.value.maintenance:all.value.compliance).map(x=>({value:x.id,label:label(type.toLowerCase(),x)}));f.type='select';}}return d})
function label(key,record){const v=record.values||record;if(key==='vehicle')return [v.registrationNumber,v.make,v.model].filter(Boolean).join(' · ')||record.id;if(key==='driver')return v.name||record.id;if(key==='loan')return [v.lender,v.accountReference].filter(Boolean).join(' · ')||record.id;if(key==='compliance')return [v.complianceType,v.referenceNumber].filter(Boolean).join(' · ')||record.id;if(key==='maintenance')return [v.maintenanceType,v.vendor].filter(Boolean).join(' · ')||record.id;if(key==='settlement'){const sourceType=v.sourceType||'Source';const source=[...all.value.maintenance,...all.value.compliance].find(x=>x.id===v.sourceId);return `${sourceType} · ${source?label(sourceType.toLowerCase(),source):v.sourceId||'Payment'}`}return record.id}
const live=rows=>(rows||[]).filter(x=>!x?.deletedAt&&!x?.deleted)
const sourcePayments=sourceId=>live(performanceSnapshot.value?.settlements).filter(x=>x.sourceId===sourceId && String(x.direction || (x.settlementType==='Receipt'?'IN':'OUT')).toUpperCase()==='OUT')
const sumPayments=sourceId=>sourcePayments(sourceId).reduce((s,x)=>s+(Number(x.amount)||0),0)
const loanHistory=record=>{const id=record.id;const s=performanceSnapshot.value||{};return [...live(s.loanPayments).filter(x=>x.loanId===id).map(x=>({kind:'Payment',date:x.paidOn,amount:Number(x.amount)||0})),...live(s.prepayments).filter(x=>x.loanId===id).map(x=>({kind:'Prepayment',date:x.paidOn,amount:Number(x.amount)||0}))].sort((a,b)=>String(b.date).localeCompare(String(a.date)))}
const sourcePaymentHistory=record=>sourcePayments(record.id).sort((a,b)=>String(b.settledOn||b.paidOn||'').localeCompare(String(a.settledOn||a.paidOn||'')))
const loanPaymentHistory=computed(()=>{const s=performanceSnapshot.value||{};const loans=live(s.loans);const labelLoan=id=>{const loan=loans.find(x=>x.id===id);return loan?label('loan',loan):id};return [...live(s.loanPayments).map(x=>({id:x.id,kind:'EMI payment',date:x.paidOn,amount:Number(x.amount)||0,loan:labelLoan(x.loanId),notes:x.notes||''})),...live(s.prepayments).map(x=>({id:x.id,kind:'Prepayment',date:x.paidOn,amount:Number(x.amount)||0,loan:labelLoan(x.loanId),notes:x.notes||''}))].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))})
const maintenancePaymentHistory=computed(()=>{const s=performanceSnapshot.value||{};return live(s.settlements).filter(x=>x.sourceType==='Maintenance'&&String(x.direction || (x.settlementType==='Receipt'?'IN':'OUT')).toUpperCase()==='OUT').map(x=>{const record=all.value.maintenance.find(r=>r.id===x.sourceId);return {id:x.id,date:x.settledOn||x.paidOn,amount:Number(x.amount)||0,maintenance:record?label('maintenance',record):x.sourceId,notes:x.notes||''}}).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))})
const compliancePaymentHistory=computed(()=>{const s=performanceSnapshot.value||{};return live(s.settlements).filter(x=>x.sourceType==='Compliance'&&String(x.direction || (x.settlementType==='Receipt'?'IN':'OUT')).toUpperCase()==='OUT').map(x=>{const record=all.value.compliance.find(r=>r.id===x.sourceId);return {id:x.id,date:x.settledOn||x.paidOn,amount:Number(x.amount)||0,compliance:record?label('compliance',record):x.sourceId,notes:x.notes||''}}).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))})
const asOfDate=()=>getKfeReferenceNow()
function complianceProvision(record){const v=record.values||record;const from=new Date(v.validFrom),to=new Date(v.validUntil),asOf=asOfDate();const cost=Number(v.cost)||0;if(!cost||Number.isNaN(from.getTime())||Number.isNaN(to.getTime())||to<=from)return 0;const hi=new Date(Math.min(to.getTime(),asOf.getTime()));const lo=new Date(Math.max(from.getTime(),0));if(hi<=lo)return 0;return cost*Math.max(0,hi-lo)/(to-lo)}
function entityFinancial(record,context=selected.value){const id=record.id;const v=record.values||record;const paid=sumPayments(id);if(context==='loan'){const snap=performanceSnapshot.value||{};const loan=live(snap.loans).find(x=>x.id===id);if(!loan)return null;const position=deriveLoanPosition({loan,payments:live(snap.loanPayments),prepayments:live(snap.prepayments),asOf:asOfDate()});const dueRows=(position.schedule||[]).filter(r=>new Date(r.dueDate)<=asOfDate());const paidDueRows=dueRows.filter(r=>Number(r.paidAmount||0)+0.005>=Number(r.originalEmiAmount||0));const overdueRows=position.overdue||[];const delayedInterest=overdueRows.reduce((s,r)=>s+Math.max(0,Number(r.unpaidOverdueInterest||0)),0);return {kind:'loan',principal:Number(loan.principal)||0,paid:position.actualPaid||0,prepaid:position.actualPrepayment||0,pending:Math.max(0,(position.scheduledDue||0)-(position.actualPaid||0)),remaining:position.outstandingPrincipal||0,emi:position.emi||0,overdue:position.totalOverdue||0,totalOverdue:position.totalOverdue||0,scheduledDue:position.scheduledDue||0,dueCount:dueRows.length,paidDueCount:paidDueRows.length,pendingDueCount:Math.max(0,dueRows.length-paidDueRows.length),delayedMonths:overdueRows.length,overduePrincipal:overdueRows.reduce((s,r)=>s+Number(r.unpaidPrincipal||0),0),overdueScheduledInterest:overdueRows.reduce((s,r)=>s+Number(r.unpaidScheduledInterest||0),0),delayedInterest,nextDue:(position.schedule||[]).find(r=>new Date(r.dueDate)>asOfDate())?.dueDate||null}}
if(context==='compliance'){const provision=complianceProvision(record);return {kind:'compliance',cost:Number(v.cost)||0,provision,paid,remaining:provision-paid}}
if(context==='maintenance'){const cost=Number(v.cost)||0;const maintenanceProvision=Number(performanceMetrics.value?.maintenanceProvision);return {kind:'maintenance',cost,paid,remaining:cost-paid,maintenanceProvision:Number.isFinite(maintenanceProvision)?maintenanceProvision:null}}
return null}
function actionDefinitionFor(kind){return ADMIN_FORM_DEFINITIONS[kind]}
function openAction(kind,record){const v=record.values||{};actionKey.value=kind;actionRecord.value=record;paymentCalculated.value=false;paymentConfirmed.value=false;const suggested=kind==='loanPayment'?Math.max(0,Number(entityFinancial(record)?.overdue||entityFinancial(record)?.emi||0)):kind==='prepayment'?Math.max(0,Number(entityFinancial(record)?.remaining||0)):Math.max(0,Number(entityFinancial(record)?.remaining||v.cost||0));actionDraft.value=kind==='settlement'?{settledOn:asOfDate().toISOString().slice(0,10),amount:suggested}:kind==='loanPayment'?{loanId:record.id,paidOn:asOfDate().toISOString().slice(0,10),amount:suggested}:kind==='prepayment'?{loanId:record.id,paidOn:asOfDate().toISOString().slice(0,10),amount:suggested}:{}}
function closeAction(){actionKey.value=null;actionRecord.value=null;actionDraft.value={};paymentCalculated.value=false;paymentConfirmed.value=false}
const loanPaymentPreview=computed(()=>{if(actionKey.value!=='loanPayment'||!actionRecord.value||!paymentCalculated.value)return null;const s=performanceSnapshot.value||{};const amount=Number(actionDraft.value?.amount)||0;const paidOn=actionDraft.value?.paidOn||asOfDate();if(amount<=0)return {available:false,reason:'Enter a payment amount.'};const loan=live(s.loans).find(x=>x.id===actionRecord.value.id)||actionRecord.value;return paymentAllocationPreview({loan,payments:live(s.loanPayments),prepayments:live(s.prepayments),amount,paidOn})})
const loanScheduleDetails=record=>{const s=performanceSnapshot.value||{};const loan=live(s.loans).find(x=>x.id===record.id)||record;const position=deriveLoanPosition({loan,payments:live(s.loanPayments),prepayments:live(s.prepayments),asOf:asOfDate()});const dueRows=(position.schedule||[]).filter(row=>new Date(row.dueDate)<=asOfDate());const overdueRows=position.overdue||[];return {loan,position,dueRows,unpaidRows:overdueRows}}
const editingRecord=computed(()=>editing.value!==null?records.value.find(x=>x.id===editing.value)||null:null)
const editingFinancial=computed(()=>editingRecord.value?entityFinancial(editingRecord.value):null)
const actionDefinition=computed(()=>{const d=actionKey.value?actionDefinitionFor(actionKey.value):null;if(!d)return null;const copy=cloneForForm(d);if(actionKey.value==='settlement')copy.fields=copy.fields.filter(f=>!['settlementType','sourceType','sourceId'].includes(f.key));for(const f of copy.fields)if(f.key==='loanId')f.options=all.value.loan.map(x=>({value:x.id,label:label('loan',x)}));return copy})
function display(value){for(const k of ['vehicle','driver','loan']){const found=all.value[k].find(x=>x.id===value);if(found)return label(k,found)}return value}
async function load(){loading.value=true;error.value='';try{records.value=await AdminService.list(selected.value);for(const k of Object.keys(all.value))all.value[k]=await AdminService.list(k);loanReadModel.value=await LoanReadModelService.getLoanReadModel(getKfeReferenceNow());performanceSnapshot.value=await PerformanceService.getSnapshot();const dates=[...(performanceSnapshot.value?.vehicles||[]).map(x=>x.acquiredOn),...(performanceSnapshot.value?.shifts||[]).map(x=>x.shiftStartAt),...(performanceSnapshot.value?.maintenance||[]).map(x=>x.performedOn),...(performanceSnapshot.value?.compliance||[]).map(x=>x.validFrom)].filter(Boolean).map(x=>new Date(x)).filter(x=>!Number.isNaN(x.getTime()));const from=dates.length?new Date(Math.min(...dates.map(x=>x.getTime()))):new Date(asOfDate().getFullYear(),asOfDate().getMonth(),1);performanceMetrics.value=PerformanceService.getMetrics(performanceSnapshot.value,{from,to:asOfDate()})}catch(e){error.value=e.message||'Unable to load records.'}finally{loading.value=false}}
function choose(key){selected.value=key;editing.value=null;draft.value={};formOpen.value=false;closeAction();if(key==='prepayment')resetPrepayment();notice.value='';load()}
function chooseGroup(group){choose(group.forms[0])}
function onCategoryTouchStart(event){categoryTouchStartX.value=event.changedTouches?.[0]?.clientX ?? null}
function onCategoryTouchEnd(event){const start=categoryTouchStartX.value;categoryTouchStartX.value=null;if(start===null)return;const end=event.changedTouches?.[0]?.clientX ?? start;const delta=end-start;if(Math.abs(delta)<45)return;const current=groups.findIndex(g=>g.key===currentGroup.value.key);const next=delta<0?Math.min(groups.length-1,current+1):Math.max(0,current-1);if(next!==current)chooseGroup(groups[next])}
function openRecords(){adminSection.value='records';error.value='';notice.value=''}
function openSettings(){adminSection.value='settings';formOpen.value=false;editing.value=null;draft.value={};error.value='';notice.value=''}
function chooseSetting(key){settingsSelected.value=key;error.value='';notice.value=''}
function chooseTheme(mode){themeSettings.value={...themeSettings.value,mode};setKfeThemeMode(mode);notice.value=`Theme set to ${mode==='light'?'Light':mode==='dark'?'Dark':'Auto'}.`}
function add(){editing.value=null;draft.value={};formOpen.value=true}
function edit(record){editing.value=record.id;draft.value=cloneForForm(record.values||{});formOpen.value=true}
const selectedPrepaymentLoan=computed(()=>all.value.loan.find(x=>x.id===prepaymentDraft.value.loanId)||null)
const selectedPrepaymentFinancial=computed(()=>selectedPrepaymentLoan.value?entityFinancial(selectedPrepaymentLoan.value,'loan'):null)
const prepaymentEstimate=computed(()=>{const loan=selectedPrepaymentLoan.value;if(!loan||!prepaymentCalculated.value)return null;const s=performanceSnapshot.value||{};const payments=live(s.loanPayments),prepayments=live(s.prepayments);const paidOn=prepaymentDraft.value.paidOn||asOfDate();const amount=Number(prepaymentDraft.value.amount)||0;const estimate=calculatePrepaymentEstimate({loan,payments,prepayments,amount,paidOn});if(!estimate.available)return {available:false,reason:estimate.reason,overdueAmount:estimate.overdueAmount||0};const hypothetical={id:'preview',loanId:loan.id,paidOn,amount:estimate.appliedAmount,status:'Applied'};const before=deriveLoanPosition({loan,payments,prepayments,asOf:paidOn});const after=deriveLoanPosition({loan,payments,prepayments:[...prepayments,hypothetical],asOf:paidOn});const beforeDate=before.scheduledFinalDate?new Date(before.scheduledFinalDate):null;const afterDate=after.scheduledFinalDate?new Date(after.scheduledFinalDate):null;const reducedMonths=beforeDate&&afterDate?Math.max(0,Math.round((beforeDate.getFullYear()-afterDate.getFullYear())*12+(beforeDate.getMonth()-afterDate.getMonth()))):0;return {...estimate,reducedMonths,remainingAfter:after.outstandingPrincipal,interestRemainingAfter:after.remainingInterest,scheduledFinalDateBefore:before.scheduledFinalDate,scheduledFinalDateAfter:after.scheduledFinalDate}})
function resetPrepayment(){prepaymentDraft.value={loanId:'',paidOn:asOfDate().toISOString().slice(0,10),amount:0,reason:'',notes:''};prepaymentCalculated.value=false;prepaymentConfirmed.value=false}
function selectPrepaymentLoan(loanId){const loan=all.value.loan.find(x=>x.id===loanId);prepaymentDraft.value={...prepaymentDraft.value,loanId,amount:Math.max(0,Number(entityFinancial(loan,'loan')?.remaining||0))};prepaymentCalculated.value=false;prepaymentConfirmed.value=false}
function calculatePrepayment(){prepaymentConfirmed.value=false;prepaymentCalculated.value=true}
async function recordCalculatedPrepayment(){if(!prepaymentEstimate.value?.available||!prepaymentConfirmed.value)return;await saveAction({loanId:prepaymentDraft.value.loanId,paidOn:prepaymentDraft.value.paidOn,amount:prepaymentEstimate.value.appliedAmount,reason:prepaymentDraft.value.reason,notes:prepaymentDraft.value.notes});prepaymentConfirmed.value=false;prepaymentCalculated.value=false}
const complianceProvisionSummary=computed(()=>{const rows=live(all.value.compliance);const provision=rows.reduce((sum,record)=>sum+complianceProvision(record),0);const paid=rows.reduce((sum,record)=>sum+sumPayments(record.id),0);return {provision,paid,balance:provision-paid}})
const maintenanceProvisionSummary=computed(()=>{const provision=Number(performanceMetrics.value?.maintenanceProvision);const paid=live(all.value.maintenance).reduce((sum,record)=>sum+sumPayments(record.id),0);return {provision:Number.isFinite(provision)?provision:0,paid,balance:(Number.isFinite(provision)?provision:0)-paid,available:Number.isFinite(provision)}})
const activeCompliance=computed(()=>live(all.value.compliance).filter(record=>{const v=record.values||record;const from=new Date(v.validFrom),to=new Date(v.validUntil),now=asOfDate();return !Number.isNaN(from.getTime())&&!Number.isNaN(to.getTime())&&from<=now&&now<=to}).sort((a,b)=>String(a.values?.validUntil||'').localeCompare(String(b.values?.validUntil||''))))
const breakEvenPreviewMetrics=computed(()=>{if(selected.value!=='breakEvenInputs'||!performanceSnapshot.value)return null;const now=getKfeReferenceNow();const monthRange=new Date(now);const start=new Date(monthRange.getTime());start.setUTCDate(1);return PerformanceService.getMetrics(performanceSnapshot.value,{from:start,to:now})})
const previewRows=computed(()=>{const m=breakEvenPreviewMetrics.value;if(!m)return [];return [['Monthly break-even',money(m.monthlyBreakEvenRevenue)],['Fixed costs',money(m.breakEvenInputs?.fixedCosts)],['Fuel cost / km',Number.isFinite(Number(m.breakEvenInputs?.fuelCostPerKm))?`₹${Number(m.breakEvenInputs.fuelCostPerKm).toFixed(2)}`:'—'],['Vehicle km',Number.isFinite(Number(m.vehicleKm))?`${Number(m.vehicleKm).toLocaleString('en-IN',{maximumFractionDigits:1})} km`:'—'],['Maintenance provision / km',Number.isFinite(Number(m.breakEvenInputs?.maintenanceProvisionPerKm))?`₹${Number(m.breakEvenInputs.maintenanceProvisionPerKm).toFixed(2)}`:'—']]})
function paymentRemaining(sourceType,sourceId){
 if(!sourceId)return 0
 const record=(sourceType==='Maintenance'?all.value.maintenance:all.value.compliance).find(x=>x.id===sourceId)
 if(!record)return 0
 const v=record.values||record
 const paid=sumPayments(sourceId)
 if(sourceType==='Compliance')return Math.max(0,complianceProvision(record)-paid)
 return Math.max(0,(Number(v.cost)||0)-paid)
}
const paymentRows=computed(()=>{const s=performanceSnapshot.value||{};const loans=live(s.loans);const byId=id=>loans.find(x=>x.id===id);return [...live(s.loanPayments).map(x=>({id:x.id,type:'Loan payment',date:x.paidOn,amount:Number(x.amount)||0,loan:byId(x.loanId),notes:x.notes||'',reason:''})),...live(s.prepayments).map(x=>({id:x.id,type:'Prepayment',date:x.paidOn,amount:Number(x.amount)||0,loan:byId(x.loanId),notes:x.notes||'',reason:x.reason||''}))].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))})
const prepaymentPreview=computed(()=>{if(actionKey.value!=='prepayment'||!actionRecord.value)return null;const f=entityFinancial(actionRecord.value);const amount=Number(actionDraft.value?.amount)||0;return {outstanding:Number(f?.remaining)||0,amount,after:Math.max(0,(Number(f?.remaining)||0)-amount)}})
function updatePaymentDraft(values){draft.value={...values}}
async function save(values){loading.value=true;error.value='';notice.value='';try{const id=editing.value;const payload=(selected.value==='compliance'||selected.value==='maintenance')?{...values,cost:Number(values.cost)||0}:values;const saved=await AdminService.save(selected.value,payload,id);if(id===null&&(selected.value==='compliance'||selected.value==='maintenance')&&Number(payload.cost)>0){const paidOn=selected.value==='maintenance'?payload.performedOn:payload.validFrom;await AdminService.save('settlement',{settlementType:'Payment',sourceType:selected.value==='maintenance'?'Maintenance':'Compliance',sourceId:saved.id,settledOn:paidOn,amount:Number(payload.cost)})}notice.value=id!==null?'Record updated successfully.':`${baseDefinition.value?.createLabel||baseDefinition.value?.title||'Record'} created successfully.`;editing.value=null;draft.value={};formOpen.value=false;await load()}catch(e){error.value=e.validation?Object.values(e.validation).join(' '):e.message||'Save failed.'}finally{loading.value=false}}
async function saveAction(values){loading.value=true;error.value='';notice.value='';try{const payload=actionKey.value==='settlement'?{...values,settlementType:'Payment',sourceType:selected.value==='maintenance'?'Maintenance':'Compliance',sourceId:actionRecord.value?.id}:values;await AdminService.save(actionKey.value,payload);notice.value=actionKey.value==='loanPayment'?'Loan payment recorded.':actionKey.value==='prepayment'?'Prepayment recorded.':'Payment recorded.';closeAction();await load()}catch(e){error.value=e.validation?Object.values(e.validation).join(' '):e.message||'Payment failed.'}finally{loading.value=false}}
async function remove(record){if(!confirm('Delete this source record? Related records may prevent deletion.'))return;loading.value=true;error.value='';try{await AdminService.remove(selected.value,record.id);notice.value='Record deleted.';await load()}catch(e){error.value=e.message||'Delete failed.'}finally{loading.value=false}}
async function resetData(){if(!confirm('Reset all KFE data? Create a backup first if you may need the current data.'))return;if(!confirm('Final confirmation: permanently delete all current KFE records?'))return;loading.value=true;error.value='';notice.value='';try{await BackupService.resetData();notice.value='All canonical KFE data has been reset.'}catch(e){error.value=e.message||'Data reset failed.'}finally{loading.value=false}}
watch([adminSection,selected,settingsSelected],persistAdminNavigation)
onMounted(()=>{restoreAdminNavigation();load()})
</script>

<template>
<section class="admin-page" aria-label="Admin">
<header class="admin-head"><div><div class="eyebrow">ADMIN · MASTER CONTROL</div><h1>Admin</h1></div><button class="settings-link" :class="{active:adminSection==='settings'}" @click="adminSection==='settings'?openRecords():openSettings()" aria-label="Settings and Data"><span>⚙</span><strong>Settings &amp; Data</strong></button></header>
<template v-if="adminSection==='records'">
<nav class="category-slider" aria-label="Business control categories" @touchstart="onCategoryTouchStart" @touchend="onCategoryTouchEnd"><button v-for="group in groups" :key="group.key" class="category-tab" :class="{active:currentGroup.key===group.key}" @click="chooseGroup(group)"><span class="category-icon">{{group.icon}}</span><span>{{group.title}}</span></button></nav>
<section class="workspace"><div class="workspace-head"><div><div class="section-label">{{currentGroup.title}}</div><h2>{{baseDefinition.title}}</h2><p>{{currentGroup.description}}</p></div><button v-if="selected!=='settlement'&&selected!=='prepayment'" class="primary" @click="add">＋ Create {{baseDefinition.createLabel||baseDefinition.title}}</button></div>
<p v-if="selected==='prepayment'" class="form-note">Prepayment is an explicit admin action. It uses the live remaining balance and records only after calculation and confirmation.</p>
<nav class="record-tabs" :aria-label="currentGroup.title"><button v-for="key in currentGroup.forms" :key="key" :class="{active:selected===key}" @click="choose(key)">{{ADMIN_FORM_DEFINITIONS[key].collectionTitle||ADMIN_FORM_DEFINITIONS[key].title}}</button></nav>
