<div v-if="formOpen && editingFinancial && (selected==='compliance'||selected==='maintenance')" class="entity-form-summary"><div class="section-label">CURRENT PROVISION · READ ONLY</div><div class="finance-metrics"><div><span>Current Provision Amount</span><strong>{{money(editingFinancial.kind==='compliance'?editingFinancial.provision:editingFinancial.maintenanceProvision)}}</strong></div></div></div><div v-if="formOpen && editingFinancial" class="entity-form-summary"><div class="section-label">DERIVED · READ ONLY</div><div v-if="editingFinancial.kind==='loan'&&editingFinancial.remaining<=0" class="loan-closed-sanity"><strong>Loan fully paid</strong><span>Remaining balance is ₹0 — this is the payment sanity check.</span></div><div class="finance-metrics" v-if="editingFinancial.kind==='loan'"><div><span>Loan amount</span><strong>{{money(editingFinancial.principal)}}</strong></div><div><span>Paid</span><strong>{{money(editingFinancial.paid)}}</strong></div><div><span>Pending</span><strong>{{money(editingFinancial.pending)}}</strong></div><div><span>Prepayment</span><strong>{{money(editingFinancial.prepaid)}}</strong></div><div><span>Remaining</span><strong>{{money(editingFinancial.remaining)}}</strong></div></div><div class="finance-metrics" v-else><div><span>Provision amount</span><strong>{{money(editingFinancial.provision ?? editingFinancial.maintenanceProvision)}}</strong></div><div><span>Actual cost</span><strong>{{money(editingFinancial.cost)}}</strong></div><div><span>Paid</span><strong>{{money(editingFinancial.paid)}}</strong></div><div><span>Remaining / provision balance</span><strong>{{money(editingFinancial.remaining)}}</strong></div></div></div><UniversalAdminForm v-if="formOpen && selected!=='settlement'" :definition="activeDefinition" :model-value="draft" :busy="loading" @update:model-value="updatePaymentDraft" @submit="save" @cancel="formOpen=false;editing=null;draft={}" :submit-label="editing!==null?'Update record':'Save record'" />
<div v-if="formOpen && selected==='breakEvenInputs'" class="breakeven-preview" aria-label="Current calculated break-even preview"><div class="section-label">DERIVED · READ ONLY</div><h3>Current calculated break-even</h3><p>These values come from KFE's authoritative records; only maintenance provision per km is configured above.</p><div class="metric-grid"><div v-for="row in previewRows" :key="row[0]"><span>{{row[0]}}</span><strong>{{row[1]}}</strong></div></div></div>
<div v-else-if="selected==='prepayment'" class="prepayment-screen"><div class="section-label">LOAN PREPAYMENT</div><h3>Calculate a prepayment</h3><p class="form-note">Select a loan. The remaining loan balance is prefilled. Nothing is recorded until you calculate, review the reduced tenure, confirm, and continue.</p><div class="prepayment-form-grid"><label class="form-field"><span class="field-label">Loan</span><select :value="prepaymentDraft.loanId" :disabled="loading" @change="selectPrepaymentLoan($event.target.value)"><option value="">Select loan…</option><option v-for="loan in all.loan" :key="loan.id" :value="loan.id">{{label('loan',loan)}}</option></select></label><label class="form-field"><span class="field-label">Remaining loan amount</span><input :value="money(selectedPrepaymentFinancial?.remaining||0)" readonly /></label><label class="form-field"><span class="field-label">Prepayment amount</span><input v-model.number="prepaymentDraft.amount" type="number" min="0" step="0.01" :disabled="loading" /></label><label class="form-field"><span class="field-label">Payment date</span><input v-model="prepaymentDraft.paidOn" type="date" :disabled="loading" /></label></div><div class="form-actions"><button type="button" class="primary" :disabled="!prepaymentDraft.loanId||Number(prepaymentDraft.amount)<=0||loading" @click="calculatePrepayment">Calculate</button></div><div v-if="prepaymentCalculated&&prepaymentEstimate" class="prepayment-calculation"><div v-if="prepaymentEstimate.available" class="finance-metrics"><div><span>Prepayment</span><strong>{{money(prepaymentEstimate.appliedAmount)}}</strong></div><div><span>Remaining after payment</span><strong>{{money(prepaymentEstimate.remainingAfter)}}</strong></div><div><span>Reduced tenure</span><strong>{{prepaymentEstimate.reducedMonths}} month{{prepaymentEstimate.reducedMonths===1?'':'s'}}</strong></div><div><span>Interest remaining after</span><strong>{{money(prepaymentEstimate.interestRemainingAfter)}}</strong></div><div><span>Loan closes</span><strong>{{prepaymentEstimate.closesLoan?'Yes':'No'}}</strong></div></div><p v-else class="message error">{{prepaymentEstimate.reason==='OVERDUE_EMI_MUST_BE_SETTLED_FIRST'?'Overdue EMI must be settled before prepayment.':prepaymentEstimate.reason}}</p><template v-if="prepaymentEstimate.available"><label class="confirmation-line"><input v-model="prepaymentConfirmed" type="checkbox" /> <span>I confirm this calculated prepayment and want to continue to payment.</span></label><div class="form-actions"><button type="button" class="secondary" @click="resetPrepayment">Cancel</button><button type="button" class="primary" :disabled="!prepaymentConfirmed||loading" @click="recordCalculatedPrepayment">Continue to pay</button></div></template></div></div>
<div v-else-if="selected==='settlement'" class="payment-history"><div v-if="paymentRows.length" class="record-list"><article v-for="item in paymentRows" :key="item.type+item.id" class="record"><div><div class="record-title"><strong>{{item.type}}</strong><span>Loan payment history</span></div><small>{{item.date?.slice(0,10)}} · {{item.loan ? label('loan',item.loan) : item.loanId}}</small><div class="finance-metrics"><div><span>Amount</span><strong>{{money(item.amount)}}</strong></div><div v-if="item.reason"><span>Reason</span><strong>{{item.reason}}</strong></div><div v-if="item.notes"><span>Notes</span><strong>{{item.notes}}</strong></div></div></div></article></div><div v-else class="empty"><div class="empty-icon">₹</div><strong>No loan payments or prepayments yet</strong><span>Record a loan payment or prepayment from the Loans screen.</span></div></div>
<section v-if="selected==='loan'" class="payment-history-section"><div class="section-label">LOAN PAYMENT HISTORY</div><h3>Everything paid toward loans</h3><p class="form-note">EMI payments and prepayments are shown here only. Maintenance and compliance payments never appear in this history.</p><div v-if="loanPaymentHistory.length" class="payment-history-list"><article v-for="item in loanPaymentHistory" :key="item.kind+item.id" class="payment-history-row"><div><strong>{{item.kind}}</strong><span>{{item.loan}}</span></div><div><strong>{{money(item.amount)}}</strong><span>{{item.date?.slice(0,10)}}<template v-if="item.notes"> · {{item.notes}}</template></span></div></article></div><div v-else class="empty compact"><strong>No loan payments yet</strong><span>Payments recorded from the Loans section will appear here.</span></div></section>
<section v-if="selected==='maintenance'" class="payment-history-section"><div class="section-label">MAINTENANCE PAYMENT HISTORY</div><h3>Everything paid for maintenance</h3><p class="form-note">Only maintenance-linked payments are shown in this history.</p><div v-if="maintenancePaymentHistory.length" class="payment-history-list"><article v-for="item in maintenancePaymentHistory" :key="item.id" class="payment-history-row"><div><strong>{{item.maintenance}}</strong><span>Maintenance payment</span></div><div><strong>{{money(item.amount)}}</strong><span>{{item.date?.slice(0,10)}}<template v-if="item.notes"> · {{item.notes}}</template></span></div></article></div><div v-else class="empty compact"><strong>No maintenance payments yet</strong><span>Payments recorded against maintenance records will appear here.</span></div></section>
<section v-if="selected==='compliance'" class="payment-history-section"><div class="section-label">COMPLIANCE PAYMENT HISTORY</div><h3>Everything paid for compliance</h3><p class="form-note">Only compliance-linked payments are shown in this history.</p><div v-if="compliancePaymentHistory.length" class="payment-history-list"><article v-for="item in compliancePaymentHistory" :key="item.id" class="payment-history-row"><div><strong>{{item.compliance}}</strong><span>Compliance payment</span></div><div><strong>{{money(item.amount)}}</strong><span>{{item.date?.slice(0,10)}}<template v-if="item.notes"> · {{item.notes}}</template></span></div></article></div><div v-else class="empty compact"><strong>No compliance payments yet</strong><span>Payments recorded against compliance records will appear here.</span></div></section>
